// eface: empty interface
var a interface{} = 42
// a 底层: eface{ _type: *intType, data: 指向 42 }

// iface: non-empty interface
var w io.Writer = os.Stdout
// w 底层: iface{ tab: *itab(io.Writer, *os.File), data: 指向 os.Stdout }

// interface 判 nil 的坑
var p *int = nil
var i interface{} = p
fmt.Println(i == nil)  // false!
// i 的 eface{ _type: *intType, data: nil }
// _type 不为 nil，所以 i != nil

type Sizer interface {
	Size() int
}

type File struct { size int }
func (f *File) Size() int { return f.size } // 指针接收者

var _ Sizer = &File{} // ✅ *File 实现了 Sizer
var _ Sizer = File{}  // ❌ 编译错误：File 没有实现 Sizer

// 如果改为值接收者：
// func (f File) Size() int { return f.size }
// 则 File 和 *File 都实现了 Sizer

// 泛型 Map 函数
func Map[T, U any](s []T, f func(T) U) []U {
	result := make([]U, len(s))
	for i, v := range s {
		result[i] = f(v)
	}
	return result
}

// 类型集合约束
type Number interface {
	~int | ~int64 | ~float64
}
func Sum[T Number](nums []T) T {
	var total T
	for _, n := range nums {
		total += n
	}
	return total
}

